-- create_views.sql - reporting views
CREATE OR REPLACE VIEW aerospace_parts_inventory_2_db.core.v_story_summary AS
SELECT
    COUNT(*)                        AS total_tasks,
    SUM(CASE WHEN status = 'DONE' THEN 1 ELSE 0 END) AS completed_tasks
FROM aerospace_parts_inventory_2_db.core.story_tasks;

CREATE OR REPLACE VIEW aerospace_parts_inventory_2_db.core.v_requirements_coverage AS
SELECT
    coverage_status,
    COUNT(*) AS items
FROM aerospace_parts_inventory_2_db.core.requirements_traceability
GROUP BY coverage_status;
